// setup is the setup source basename ("setupame"), or NULL/"" for a
// global list. Linear: only ever walked while a combo is open or for
// one preview per open chr node.
static const char *imguiAilistName(const char *setup, unsigned int id)
{
	const char *key = setup ? setup : "";
	for (unsigned int i = 0; i < sizeof(g_ImGuiAilistNames) / sizeof(g_ImGuiAilistNames[0]); i++) {
		if (g_ImGuiAilistNames[i].id == id && strcmp(g_ImGuiAilistNames[i].setup, key) == 0) {
			return g_ImGuiAilistNames[i].name;
		}
	}
	return NULL;
}

